#ifndef _ALLIST_H_
#define _ALLIST_H_

#include <Arduino.h>
#include <memory>

template <typename T>
class Node
{
public:
  std::shared_ptr<T> data; // Pointeur partagé vers les données
  std::unique_ptr<Node<T>> next; // Pointeur unique vers le nœud suivant

  Node(const std::shared_ptr<T> &data) : data(data), next(nullptr) {}
};

template <typename T>
class al_llist
{
private:
  std::unique_ptr<Node<T>> head; 
  mutable size_t frameMaxLen = 0;

  // Ajout des méthodes pour le tri par fusion
  void mergeSort(std::unique_ptr<Node<T>>& headRef, int (*cmp)(T&, T&))
  {
    if (!headRef)
    {
        return;
    }

    std::unique_ptr<Node<T>> a = std::move(headRef);
    std::unique_ptr<Node<T>> b;

    frontBackSplit(std::move(a), b);

    mergeSort(a, cmp);
    mergeSort(b, cmp);

    headRef = merge(std::move(a), std::move(b), cmp);
  }

  std::unique_ptr<Node<T>> merge(std::unique_ptr<Node<T>> a, std::unique_ptr<Node<T>> b, int (*cmp)(T&, T&))
  {
    if (!a)
        return b;
    else if (!b)
        return a;

    if (cmp(*a->data, *b->data) <= 0)
    {
        a->next = merge(std::move(a->next), std::move(b), cmp);
        return a;
    }
    else
    {
        b->next = merge(std::move(a), std::move(b->next), cmp);
        return b;
    }
  }

  void frontBackSplit(std::unique_ptr<Node<T>> source, std::unique_ptr<Node<T>>& frontRef, std::unique_ptr<Node<T>>& backRef)
  {
    if (!source)
    {
        frontRef = nullptr;
        backRef = nullptr;
        return;
    }

    std::unique_ptr<Node<T>> slow = std::move(source);
    std::unique_ptr<Node<T>> fast = std::move(slow->next);

    while (fast)
    {
        fast = std::move(fast->next);
        if (fast)
        {
            slow = std::move(slow->next);
            fast = std::move(fast->next);
        }
    }

    frontRef = std::move(slow);
    backRef = std::move(frontRef->next);
    frontRef->next = nullptr;
  }

public:
  // ... [Les autres méthodes publiques de la classe]

  void sort(int (*cmp)(T&, T&))
  {
    mergeSort(head, cmp);
  }
};

#endif // _ALLIST_H_
